const chibiDefaults={hair:'cocoa',style:'bob',eyes:'round',mouth:'smile',face:'round',skin:'milk',outfit:'rose',blush:true,cut:'dress'};
function openChibiSelector(){const d=homePanel(`<h2>设置Q版形象</h2><div class="living-role-row">${chibiAvatar('me')}<div><b>${escapeHtml(profile.name)}</b><small>我的形象</small></div><button data-chibi-person="me">捏脸 / 换装</button></div>${roles.map(r=>`<div class="living-role-row">${chibiAvatar(r.id)}<div><b>${escapeHtml(r.name)}</b><small>${living.guests.includes(r.id)?'正在家园做客':'可以单独保存形象'}</small></div><button data-chibi-person="${escapeHtml(r.id)}">捏脸 / 换装</button></div>`).join('')}`);d.querySelectorAll('[data-chibi-person]').forEach(b=>b.onclick=()=>openChibiEditor(b.dataset.chibiPerson))}
function defaultChibi(id){return {...chibiDefaults,...(id!=='me'&&roles.findIndex(r=>r.id===id)%2===1?{cut:'suit',style:'short',hair:'black',outfit:'rose'}:{})}}
function chibiAvatar(id='me',draft=null){const a={...defaultChibi(id),...(living.avatars[id]||{}),...(draft||{})},uploaded=!draft&&mediaCache.get('chibi:'+id);if(uploaded)return `<span class="chibi"><img src="${uploaded}" alt="Q版形象"></span>`;const hair={cocoa:'#735248',black:'#403b48',honey:'#c49a67',pink:'#c995ab'}[a.hair]||'#735248',skin={milk:'#ffeadc',honey:'#edc5a5',cocoa:'#c58e73'}[a.skin]||'#ffeadc',cloth=PalaisHome.clothes[a.outfit]?.color||'#e8a9b9',eye=a.eyes==='star'?'#9278a1':a.eyes==='soft'?'#748c82':'#6b514b',back=a.style==='long'?`<path d="M34 41Q21 66 28 108Q39 117 48 103L84 105Q101 112 104 98L96 41Z" fill="${hair}"/>`:a.style==='bun'?`<circle cx="32" cy="32" r="17" fill="${hair}"/><circle cx="96" cy="32" r="17" fill="${hair}"/>`:'',eyes=a.eyes==='soft'?'<path d="M43 62q5-5 10 0m22 0q5-5 10 0" fill="none" stroke="'+eye+'" stroke-width="3" stroke-linecap="round"/>':`<ellipse cx="48" cy="62" rx="6" ry="8" fill="${eye}"/><ellipse cx="80" cy="62" rx="6" ry="8" fill="${eye}"/><circle cx="46" cy="59" r="2.2" fill="white"/><circle cx="78" cy="59" r="2.2" fill="white"/><circle cx="50" cy="66" r="1" fill="#e9d8c7"/><circle cx="82" cy="66" r="1" fill="#e9d8c7"/>`,mouth=a.mouth==='cat'?'<path d="M58 78q3 5 6 0q3 5 6 0"/>':a.mouth==='tiny'?'<ellipse cx="64" cy="79" rx="2" ry="2.5" fill="#bf8c85" stroke="none"/>':'<path d="M59 77q5 6 10 0"/>';return `<span class="chibi" role="img" aria-label="可自定义的Q版小人"><svg viewBox="0 0 128 180" xmlns="http://www.w3.org/2000/svg"><ellipse cx="64" cy="171" rx="28" ry="4" fill="#bca0af" opacity=".15"/>${back}<path d="M49 143l-1 20q0 7 8 5l4-26m18 1 1 20q0 7-8 5l-4-26" fill="${skin}" stroke="#d8b7a8" stroke-width="1"/><path d="M46 165q7-4 12 0v5H43q-2-4 3-5m35 0q-7-4-12 0v5h15q2-4-3-5" fill="#8e737d"/><path d="M43 104q-13 9-16 28q3 6 8 2l13-22m37-8q13 9 16 28q-3 6-8 2l-13-22" fill="${skin}" stroke="#d7b5a5" stroke-width="1"/>${a.cut==='suit'?`<path d="M45 98h38l5 32H40Z" fill="${cloth}" stroke="#c497a7"/><path d="M41 130h46l-4 21H67l-3-12-3 12H45Z" fill="#8a7d91"/>`:`<path d="M47 98h34l12 45q-29 14-58 0Z" fill="${cloth}" stroke="#c497a7" stroke-width="1.1"/>`}<path d="M47 101l17 12 17-12-2-5H49Z" fill="#fff9ee"/><path d="M64 110v29M39 139q24 8 50 0" fill="none" stroke="#ffffff" stroke-opacity=".55" stroke-width="2"/><path d="M57 111q-10-8-12-1q2 8 12 3m14-2q10-8 12-1q-2 8-12 3" fill="#fff2df"/><circle cx="64" cy="112" r="3" fill="#f8ddc0"/><rect x="57" y="88" width="14" height="15" rx="5" fill="${skin}"/><ellipse cx="29" cy="63" rx="7" ry="10" fill="${skin}"/><ellipse cx="99" cy="63" rx="7" ry="10" fill="${skin}"/><path d="M28 43Q29 14 64 14T100 43L99 67Q97 ${a.face==='oval'?101:97} 64 99Q31 97 29 68Z" fill="${skin}" stroke="#d6b09d" stroke-width="1.1"/><path d="M26 49Q20 10 61 10Q106 8 103 52L92 40Q77 43 60 25Q47 45 27 51Z" fill="${hair}"/><path d="M35 31q12-16 28-15m-9 2q13-6 29 7" fill="none" stroke="#fff5d6" stroke-opacity=".22" stroke-width="4" stroke-linecap="round"/>${a.style==='short'?`<path d="M26 44l2 26 9-17m64-9-1 26-10-17" fill="${hair}"/>`:a.style==='bob'?`<path d="M26 42q-8 28 3 46l11-4-4-33m64-9q8 28-3 46l-11-4 4-33" fill="${hair}"/>`:''}<path d="M42 48l10-2m24 0 10 2" fill="none" stroke="${hair}" stroke-width="2" stroke-linecap="round"/>${eyes}<path d="M62 70q2 2 4 0" fill="none" stroke="#ddb49f" stroke-width="1.3"/><g fill="none" stroke="#b57e78" stroke-width="1.7" stroke-linecap="round">${mouth}</g>${a.blush?'<ellipse cx="39" cy="75" rx="7" ry="4" fill="#efa9ac" opacity=".4"/><ellipse cx="89" cy="75" rx="7" ry="4" fill="#efa9ac" opacity=".4"/>':''}${a.cut==='dress'?'<path d="M91 24q13-8 13 1-2 7-12 4m0-5q-6-10-10-4-2 7 9 10" fill="#f0b6c9" stroke="#c68da3" stroke-width="1"/>':''}</svg></span>`}
function homeAvatar(){return chibiAvatar('me')}
function livingBubble(id,text){livingBubbles[id]={text:String(text).slice(0,400),until:performance.now()+16000};livingUpdateBubbles()}
function livingUpdateBubbles(){for(const el of document.querySelectorAll('[data-living-bubble]')){const b=livingBubbles[el.dataset.livingBubble];el.hidden=!b||b.until<performance.now();el.textContent=b?.text||''}}
function livingHistory(id){return PalaisLiving.visible(living,id).map(e=>({...e,source:'家园',sender:undefined,content:'[家园'+(e.private?'单独交谈':'共同经历')+'] '+e.content}))}
function homeRelationshipPrompt(id,members=null){const recent=(members?PalaisLiving.publicHistory(living,id,members):PalaisLiving.visible(living,id)).slice(-30).map(e=>e.content).join('\n');return recent?'\n你亲历的家园生活记录（不包含你没在场的经历）：\n'+recent+'\n这些经历与日常私聊连续，可以自然提起，不要编造未发生的活动。':''}
function commitHomeAction(action){const result=PalaisHome.apply(homeland,action);let nextWallet=wallet;if(action.type==='harvest'){const p=homeland.plots[action.index];if(p&&['carrot','berry'].includes(p.crop)){nextWallet=PalaisLiving.normalize(wallet);nextWallet.inventory[p.crop]=(nextWallet.inventory[p.crop]||0)+1}}const nextLiving=livingEvent(living,(action.actor||profile.name)+'：'+result.message);livingCommit(nextWallet,nextLiving,result.state);return result}
function livingMount(g){const world=$('#gameWorld');if(!world)return;const actor=$('#homeActor');if(actor){actor.innerHTML=homeAvatar()+`<small>${escapeHtml(profile.name)}</small><span class="living-bubble" data-living-bubble="me" hidden></span>`}for(const id of living.guests.filter(id=>roles.some(r=>r.id===id))){const r=roles.find(x=>x.id===id),b=document.createElement('button');b.className='home-guest';b.dataset.guest=id;b.innerHTML=chibiAvatar(id)+`<small>${escapeHtml(r.name)}</small><span class="living-bubble" data-living-bubble="${escapeHtml(id)}" hidden></span>`;b.setAttribute('aria-label','和'+r.name+'互动');b.onclick=()=>openLivingGuest(id);world.append(b)}if(g.player.room==='inside'){const b=document.createElement('button');b.className='world-hotspot indoor-kitchen';b.textContent='🍳 一起做饭';b.onclick=openLivingKitchen;world.append(b)}if(!$('#livingToolbar')){const toolbar=document.createElement('div');toolbar.id='livingToolbar';toolbar.className='living-toolbar';toolbar.innerHTML='<button id="livingInvite">邀请角色</button><button id="livingKitchen">一起做饭</button><button id="livingShop">小商店</button><button id="livingTalkHistory">家园记录</button>';$('.home-game').append(toolbar);$('#livingInvite').onclick=openLivingInvites;$('#livingKitchen').onclick=openLivingKitchen;$('#livingShop').onclick=()=>go('shop');$('#livingTalkHistory').onclick=openLivingHistory;const form=document.createElement('form');form.className='living-chatbar';form.id='livingChatForm';form.innerHTML=`<select name="target" aria-label="家园对话对象"><option value="all">大家 · 公开</option>${living.guests.map(id=>roles.find(r=>r.id===id)).filter(Boolean).map(r=>`<option value="${escapeHtml(r.id)}">单独 · ${escapeHtml(r.name)}</option>`).join('')}</select><input name="message" maxlength="1000" required aria-label="家园消息" placeholder="对身边的人说句话…"><button>${livingChatBusy?'停止':'发送'}</button>`;$('.home-game').append(form);form.onsubmit=e=>{e.preventDefault();if(livingChatBusy){livingChatController?.abort();return}const value=form.message.value.trim(),target=form.target.value;if(value)sendLivingChat(value,target).then(ok=>{if(ok&&form.isConnected)form.message.value=''})}}if($('#homeOwnership b'))$('#homeOwnership b').textContent='我的玫瑰家园 · '+living.guests.length+' 位来客';g.visitors=g.visitors||{};livingTick(g)}
function livingGuestSpot(g,i){const h=PalaisHomeWorld.maps[g.player.room].height,sign=g.player.y>h-190?-1:1;return PalaisHomeWorld.safeLocation({room:g.player.room,x:g.player.x+(i%2===0?-95:95),y:g.player.y+sign*(65+Math.floor(i/2)*85)})}
function livingTick(g){if(!g?.visitors||!$('#gameWorld'))return;const t=performance.now(),dt=Math.min(.05,(t-(g.livingLast||t))/1000);g.livingLast=t;const paused=!!document.querySelector('dialog[open]')||document.hidden;for(let i=0;i<living.guests.length;i++){const id=living.guests[i];if(!g.visitors[id])g.visitors[id]={...livingGuestSpot(g,i),path:[]};const v=g.visitors[id],job=living.jobs.find(j=>j.roleId===id&&j.status==='queued');if(!paused){if(job){if(v.jobId!==job.id){v.jobId=job.id;v.room='garden';v.x=700;v.y=570;v.path=PalaisHomeWorld.path('garden',v,job.position)}homeFollowPath(v,v.path,115,dt);if(!v.path.length&&!v.blocked)livingCompleteJob(job,g)}else{if(v.room!==g.player.room){Object.assign(v,livingGuestSpot(g,i));v.path=[]}if(Math.hypot(v.x-g.player.x,v.y-g.player.y)>140&&!v.path.length)v.path=PalaisHomeWorld.path(v.room,v,livingGuestSpot(g,i));homeFollowPath(v,v.path,95,dt)}}const el=[...document.querySelectorAll('[data-guest]')].find(el=>el.dataset.guest===id);if(el){el.hidden=v.room!==g.player.room;el.style.left=v.x+'px';el.style.top=v.y+'px';el.style.zIndex=Math.round(v.y);el.classList.toggle('walking',!!v.path.length)}}livingUpdateBubbles()}
function openLivingInvites(){const d=homePanel(`<form class="living-form" id="livingInviteForm"><h2>邀请来家里玩</h2><p class="daily-caption">最多 4 位。邀请不会自动让陌生角色互相认识，可以点击「相互介绍」。一次邀请 1 位时，家园对话会续接你们的私聊；多人时可公开聊天或选择单独交谈。</p>${roles.map(r=>`<label class="check"><input name="guest" type="checkbox" value="${escapeHtml(r.id)}" ${living.guests.includes(r.id)?'checked':''}>${escapeHtml(r.name)}</label>`).join('')||'<p>先在微信创建一位角色。</p>'}<div class="actions"><button class="secondary" type="button" id="livingIntroduce">相互介绍</button><button class="primary">确认邀请</button></div></form>`);$('#livingInviteForm').onsubmit=e=>{e.preventDefault();try{if(livingChatBusy)throw Error('请等待对话结束');const ids=[...e.target.querySelectorAll('input:checked')].map(b=>b.value);if(ids.length>4)throw Error('最多邀请 4 位');let n={...living,guests:ids,jobs:living.jobs.map(j=>j.status==='queued'&&!ids.includes(j.roleId)?{...j,status:'cancelled'}:j)};n=livingEvent(n,'用户邀请 '+ids.map(id=>roles.find(r=>r.id===id)?.name).join('、')+' 来到家园。邀请本身不代表彼此认识。',ids);livingCommit(wallet,n);d.close();renderHomeland()}catch(err){toast(err.message)}};$('#livingIntroduce').onclick=()=>{if(living.guests.length<2){toast('先确认邀请至少两位角色');return}try{const next=PalaisSocial.connect(relations,living.guests,'home','用户在家园相互介绍'),old=relations;relations=next;try{saveSocial()}catch(e){relations=old;throw e}livingCommit(wallet,livingEvent(living,'用户向在场的人互相介绍了 '+living.guests.map(id=>roles.find(r=>r.id===id)?.name).join('、')+'，他们从现在开始认识。'));toast('已相互介绍，认识关系已保存')}catch(e){toast(e.message)}}}
function openLivingGuest(id){const r=roles.find(r=>r.id===id);if(!r)return;const d=homePanel(`<h2>${escapeHtml(r.name)}</h2><div class="living-preview">${chibiAvatar(id)}</div><div class="studio-controls"><button class="secondary" id="whisperGuest">单独聊天</button><button class="secondary" id="styleGuest">设置Q版形象</button><button class="secondary" id="dispatchGuest">派遣做事</button></div><button class="secondary full" id="cookWithGuest">一起做饭</button>`);$('#whisperGuest').onclick=()=>{d.close();$('#livingChatForm select').value=id;$('#livingChatForm input').focus()};$('#styleGuest').onclick=()=>openChibiEditor(id);$('#dispatchGuest').onclick=()=>openLivingDispatch(id);$('#cookWithGuest').onclick=()=>openLivingKitchen(id)}
function openLivingKitchen(selected='all'){const d=homePanel(`<form id="livingCookForm" class="living-form"><h2>一起做饭</h2><label>和谁一起？<select name="partner"><option value="all">${living.guests.length?'所有在场的人':'自己做饭'}</option>${living.guests.map(id=>roles.find(r=>r.id===id)).filter(Boolean).map(r=>`<option value="${escapeHtml(r.id)}" ${r.id===selected?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label><p class="daily-caption">用商店食材，也能使用收获的胡萝卜与草莓。完成后记录给在场角色，下一次微信聊天可以提起。</p>${Object.entries(PalaisLiving.recipes).map(([id,r])=>`<div class="living-role-row"><span style="font-size:30px">${r.icon}</span><div><b>${r.name} · 已做好 ${wallet.inventory?.['meal:'+id]||0} 份</b><small>${Object.entries(r.need).map(([k,q])=>PalaisLiving.catalog[k].name+' '+(wallet.inventory?.[k]||0)+'/'+q).join('、')}</small></div><button type="button" data-cook-recipe="${id}">做这道</button></div>`).join('')}<button type="button" class="secondary full" id="kitchenShop">缺食材？去商店</button></form>`);$('#kitchenShop').onclick=()=>{d.close();go('shop')};d.querySelectorAll('[data-cook-recipe]').forEach(b=>b.onclick=()=>{try{const r=PalaisLiving.recipes[b.dataset.cookRecipe],id=$('#livingCookForm select').value,participants=id==='all'?living.guests:[id];if(participants.some(id=>!living.guests.includes(id)))throw Error('这位角色已经离开家园');const names=participants.map(id=>roles.find(r=>r.id===id)?.name).join('、'),text=profile.name+(names?'与'+names:'')+'一起做好了'+r.name+'。';livingCommit(PalaisLiving.cook(wallet,b.dataset.cookRecipe),livingEvent(living,text,living.guests));d.close();livingBubble('me','做好了'+r.name+'！');participants.forEach(id=>livingBubble(id,'一起做的'+r.name+'完成啦。'));toast('食材已扣除，成品与共同经历已保存')}catch(err){toast(err.message)}})}
function openLivingDispatch(id){const r=roles.find(r=>r.id===id),d=homePanel(`<form id="livingDispatchForm" class="living-form"><h2>请${escapeHtml(r.name)}帮忙</h2><label>做什么？<select name="task"><option value="plant">播种</option><option value="water">浇水</option><option value="harvest">收获</option></select></label><label>哪块菜地？<select name="plot">${homeland.plots.map((p,i)=>`<option value="${i}">菜地 ${i+1} · ${p?PalaisHome.crops[p.crop].name+(p.watered?'（已浇水）':'（待浇水）'):'空地'}</option>`).join('')}</select></label><label>播种种类<select name="crop">${Object.entries(PalaisHome.crops).map(([id,c])=>`<option value="${id}">${c.name} · ${c.cost} 积分</option>`).join('')}</select></label><p class="daily-caption">角色会走到菜地再执行任务；使用实际种植、成熟与积分规则。离开家园时暂停，回来后继续。</p><button class="primary full">确认派遣</button></form>`);$('#livingDispatchForm').onsubmit=e=>{e.preventDefault();try{if(living.jobs.some(j=>j.roleId===id&&j.status==='queued'))throw Error('TA 还有未完成的任务');const f=e.target,index=Number(f.plot.value),action={type:f.task.value,index,crop:f.crop.value,actor:r.name};PalaisHome.apply(homeland,action);const job={id:crypto.randomUUID(),roleId:id,action,status:'queued',position:{x:795+index%2*112,y:650+Math.floor(index/2)*115}};livingCommit(wallet,{...living,jobs:[...living.jobs,job].slice(-200)});d.close();livingBubble(id,'好，我去'+{plant:'播种',water:'浇水',harvest:'收获'}[action.type]+'。')}catch(err){toast(err.message)}}}
function livingCompleteJob(job,g){try{const result=PalaisHome.apply(homeland,job.action);let nextWallet=wallet;if(job.action.type==='harvest'){const p=homeland.plots[job.action.index];if(p&&['carrot','berry'].includes(p.crop)){nextWallet=PalaisLiving.normalize(wallet);nextWallet.inventory[p.crop]=(nextWallet.inventory[p.crop]||0)+1}}let n={...living,jobs:living.jobs.map(j=>j.id===job.id?{...j,status:'done'}:j)};n=livingEvent(n,(roles.find(r=>r.id===job.roleId)?.name||'角色')+'完成家园任务：'+result.message);livingCommit(nextWallet,n,result.state);livingBubble(job.roleId,result.message);homeRefreshPlots();if($('#gameTasks'))$('#gameTasks').innerHTML='✧ '+homeland.points+'<small>家园积分</small>'}catch(e){const n={...living,jobs:living.jobs.map(j=>j.id===job.id?{...j,status:'failed',error:e.message}:j)};try{livingCommit(wallet,n)}catch{g.visitors[job.roleId].blocked=true}livingBubble(job.roleId,'这次没完成：'+e.message)}}
async function sendLivingChat(value,target){if(livingChatBusy||busy||studioJob){toast('请等待当前生成结束');return false}const audience=target==='all'?living.guests.slice():[target];if(!audience.length){toast('先邀请一位角色来家里');return false}if(audience.some(id=>!living.guests.includes(id))){toast('角色已经离开家园');return false}if(!apiReady()){toast('先连接聊天 API，再来家园聊天');return false}const privateTalk=target!=='all'||living.guests.length===1;let userEvent;try{const n=livingEvent(living,profile.name+'：'+value,audience,'me',privateTalk);userEvent=n.events.at(-1);livingCommit(wallet,n)}catch(e){toast(e.message);return false}livingBubble('me',value);livingChatBusy=true;livingChatController=new AbortController();const signal=AbortSignal.any([livingChatController.signal,AbortSignal.timeout(90000)]);const button=$('#livingChatForm button');if(button)button.textContent='停止';try{for(const id of audience){const r=roles.find(r=>r.id===id);if(!r)continue;const peers=living.guests.filter(x=>x!==id).map(x=>({名字:roles.find(r=>r.id===x)?.name,认识:PalaisSocial.knows(relations,id,x)})),seen=privateTalk?PalaisLiving.visible(living,id):PalaisLiving.publicHistory(living,id,audience),daily=privateTalk?(histories[id]||[]).slice(-20).map(m=>({role:m.role,content:msgForAPI(m).content})):[];const system=PalaisCore.systemPrompt(r,worldbook,[],r.id)+'\n你现在与用户在玫瑰家园，'+(privateTalk?'正在单独交谈，可以续接你与用户的日常私聊。':'正在多人公开交谈，不读取或泄露任何私聊。')+'只扮演你自己，不代替用户做决定。未认识的来客应保持陌生，可以好奇询问，请用户介绍，不能假装熟识。\n当前其他来客：'+JSON.stringify(peers)+'\n'+(privateTalk?memoryPrompt(id):'')+'\n共同经历摘要：'+(privateTalk?sharedContext(id):'')+'\n本次所有在场者均可见的历史群聊：'+JSON.stringify(groups.flatMap(g=>groupSeen(g,id).filter(m=>audience.every(a=>(m.audience||[]).includes(a))).slice(-12).map(msgForAPI)))+'\n此处只聊天与讨论，不执行红包或亲属卡等金额指令，金额操作请在微信确认。\n以下为你亲历的近期家园记录：'+JSON.stringify(seen.slice(-24).map(e=>({内容:e.content,时间:e.createdAt})));const text=await request({...config,key},[{role:'system',content:system},...daily,{role:'user',content:value}],900,signal);if(signal.aborted)throw new DOMException('Stopped','AbortError');const content=text.replace(/\[\[(?:红包|转账|亲属卡)\|[^\]]*\]\]/g,'').trim()||'我们回到微信再确认这件事吧。';livingCommit(wallet,livingEvent(living,r.name+'：'+content,audience,id,privateTalk));livingBubble(id,content)}}catch(e){toast(friendly(e)+'，你的家园消息已经保存')}finally{livingChatBusy=false;livingChatController=null;const b=$('#livingChatForm button');if(b)b.textContent='发送';memoryTick()}return true}
function openLivingHistory(){const d=homePanel(`<h2>家园生活记录</h2><p class="daily-caption">公开活动记给当时在场者；单独交谈只记给对应角色。记录也会用于这些角色的微信私聊和共同经历整理。</p>${living.events.slice(-100).reverse().map(e=>`<div class="living-talklog"><small>${new Date(e.createdAt).toLocaleString('zh-CN')} · ${e.private?'单独交谈':'共同经历'} · ${escapeHtml(e.audience.map(id=>roles.find(r=>r.id===id)?.name||'已移除角色').join('、'))}</small><br>${escapeHtml(e.content)}</div>`).join('')||'<p>还没有共同经历。</p>'}<button class="secondary full" id="closeLivingHistory">完成</button>`);$('#closeLivingHistory').onclick=()=>d.close()}
function openChibiEditor(id='me'){livingDressing=id;let draft={...defaultChibi(id),...living.avatars[id]};const draw=()=>{const d=homePanel(`<h2>${id==='me'?'我的':escapeHtml(roles.find(r=>r.id===id)?.name||'角色')}Q版形象</h2><div class="living-preview" id="chibiLive">${chibiAvatar(id,draft)}</div><p class="daily-caption">点击即预览。用户与每位角色各自保存形象，也可以上传自己的Q版全身图。</p>${[['cut','服装版型',[['dress','连衣裙'],['suit','上衣短裤']]],['style','发型',[['bob','短波波'],['long','长发'],['short','清爽短发'],['bun','双丸子']]],['hair','发色',[['cocoa','可可'],['black','墨黑'],['honey','蜂蜜'],['pink','玫瑰']]],['eyes','眼型',[['round','圆润杏眼'],['soft','弯弯笑眼'],['star','紫藤星眸']]],['mouth','嘴型',[['smile','微笑'],['cat','猫咪嘴'],['tiny','小圆嘴']]],['skin','肤色',[['milk','奶油'],['honey','蜂蜜'],['cocoa','可可']]],['face','脸型',[['round','软圆脸'],['oval','鹅蛋脸']]]].map(([k,label,list])=>`<h3>${label}</h3><div class="chibi-choices">${list.map(([v,n])=>`<button data-chibi-key="${k}" data-chibi-value="${v}" class="${draft[k]===v?'selected':''}">${n}</button>`).join('')}</div>`).join('')}<h3>衣服 · 实时试穿</h3><div class="living-clothes">${Object.entries(PalaisHome.clothes).map(([k,c])=>`<button data-chibi-key="outfit" data-chibi-value="${k}">${chibiAvatar(id,{...draft,outfit:k})}<b>${c.name}</b><small>${homeland.owned.includes(k)?'已拥有':c.price+' 积分'}</small></button>`).join('')}</div><input hidden type="file" id="chibiUpload" accept="image/png,image/jpeg,image/webp"><div class="actions"><button class="secondary" id="uploadChibi">上传Q版图</button><button class="primary" id="saveChibi">${homeland.owned.includes(draft.outfit)?'保存形象':'购买并保存 · '+PalaisHome.clothes[draft.outfit].price+' 积分'}</button></div>`);d.querySelectorAll('[data-chibi-key]').forEach(b=>b.onclick=()=>{draft[b.dataset.chibiKey]=b.dataset.chibiValue;draw()});$('#uploadChibi').onclick=()=>$('#chibiUpload').click();$('#chibiUpload').onchange=async e=>{try{const image=await prepareImage(e.target.files[0],800);await mediaWrite('chibi:'+id,image);d.close();renderHomeland();toast('Q版形象已上传')}catch(err){toast(err.message)}};$('#saveChibi').onclick=async()=>{try{const h=PalaisLiving.clone(homeland);if(!h.owned.includes(draft.outfit)){const price=PalaisHome.clothes[draft.outfit].price;if(h.points<price)throw Error('家园积分不足');h.points-=price;h.owned.push(draft.outfit)}const oldPic=mediaCache.get('chibi:'+id)||null;await mediaWrite('chibi:'+id,null);try{livingCommit(wallet,{...living,avatars:{...living.avatars,[id]:draft}},h)}catch(e){await mediaWrite('chibi:'+id,oldPic).catch(()=>{});throw e}d.close();renderHomeland();toast('Q版形象已保存')}catch(err){toast(err.message)}}};draw()}
